import{_ as l,a0 as n,w as r,s as h,ao as k,I as p,x as i,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"C語言數據類型是如何被大多數計算機系統所支持？ | LCTT x X-CMD","titleTemplate":false,"description":"C語言數據類型是如何被大多數計算機系統所支持？ | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"C語言數據類型是如何被大多數計算機系統所支持？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"C語言數據類型是如何被大多數計算機系統所支持？ | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150122 How are C data types “supported directly by most computers”","title":"C語言數據類型是如何被大多數計算機系統所支持？","tag":"201504","desc":""},"relativePath":"201504/20150122 How are C data types “supported directly by most computers”.md","filePath":"[post].md"}'),o={name:"201504/20150122 How are C data types “supported directly by most computers”.md"};function d(g,s,y,C,u,m){const t=n("Link");return r(),h("div",null,[s[13]||(s[13]=k(`<h1 id="c語言數據類型是如何被大多數計算機系統所支持" tabindex="-1">C語言數據類型是如何被大多數計算機系統所支持？ <a class="header-anchor" href="#c語言數據類型是如何被大多數計算機系統所支持" aria-label="Permalink to “C語言數據類型是如何被大多數計算機系統所支持？”">​</a></h1><p>###問題：</p><p>在讀K&amp;R版的<em>The C Programming Language</em>一書時，我在[介紹，第3頁]看到這樣一條説明：</p><blockquote><p><strong>因為C語言提供的數據類型和控制結構可以直接被大部分計算機系統所支持，所以在實現自包含程序時所需要的運行庫文件一般很小。</strong></p></blockquote><p>這段黑體説明了什麼？能否找到一個例子來説明C語言中的某種數據類型或控制結構不被某種計算機系統直接支持呢？</p><p>###回答:</p><p>事實上，C語言中確實有不被直接支持的數據類型。</p><p>在許多嵌入式系統中，硬件上並沒有浮點運算單元。因此，如果你寫出下面的代碼：</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> y;</span></span></code></pre></div><p>可能會被轉化成下面這種形式：</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">unsigned</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3f800000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40000000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> _float_add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, y);</span></span></code></pre></div><p>然後編譯器或標準庫必須提供&#39;_float_add()&#39;的具體實現，這會佔用嵌入式系統的內存空間。依此去計算代碼在某個微型系統（譯者注：也就是指微型嵌入式系統）的實際字節數，也會發現有所增加。</p><p>另一個常見的例子是64位整型數（C語言標準中&#39;long long&#39;類型是1999年之後才出現的），這種類型在32位系統上也不能直接使用。古董級的SPARC系統則不支持整型乘法，所以在運行時必須提供乘法的實現。當然，還有一些其它例子。</p><p>####其它語言</p><p>相比起來，其它編程語言有更加複雜的基本類型。</p><p>比如，Lisp中的symbol需要大量的運行時實現支持，就像Lua中的table、Python中的string、Fortran中的array，等等。在C語言中等價的類型通常要麼不屬於標準庫（C語言沒有標準symbol或table），要麼更加簡單，而且並不需要那麼多的運行時支持（C語言中的array基本上就是指針，以NULL結尾的字符串實現起來也很簡單）。</p><p>####控制結構</p><p>異常處理是C語言中沒有的一種控制結構。非局部的退出只有&#39;setjmp()&#39;和&#39;longjmp()&#39;兩種，只能提供保存和恢復某些部分的處理器狀態。相比之下，C++運行時環境必須先遍歷函數調用棧，然後調用析構函數和異常處理函數。</p><hr>`,19)),p("p",null,[s[1]||(s[1]=i("via:",-1)),a(t,{href:"http://stackoverflow.com/questions/27977522/how-are-c-data-types-supported-directly-by-most-computers/27977605#27977605"},{default:e(()=>[...s[0]||(s[0]=[i("stackoverflow",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=i("作者：",-1)),a(t,{href:"http://stackoverflow.com/users/82294/dietrich-epp"},{default:e(()=>[...s[2]||(s[2]=[i("Dietrich Epp",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),a(t,{href:"https://github.com/KayGuoWhu"},{default:e(()=>[...s[3]||(s[3]=[i("KayGuoWhu",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創翻譯，",-1)),a(t,{href:"http://linux.cn/"},{default:e(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const F=l(o,[["render",d]]);export{b as __pageData,F as default};
